-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.invited_emails (
  email text not null,
  note text,
  invited_at timestamp with time zone default now() not null,
  list text not null,
  invited_by text,
  constraint invited_emails_pkey PRIMARY KEY (email),
  constraint invited_emails_email_check CHECK (((email = lower(TRIM(BOTH FROM email))) AND public.is_allowed_email(email))),
  constraint invited_emails_invited_by CHECK (((char_length(invited_by) >= 1) AND (char_length(invited_by) <= 100))),
  constraint invited_emails_list CHECK (((list = TRIM(BOTH FROM list)) AND ((char_length(list) >= 1) AND (char_length(list) <= 60)))),
  constraint invited_emails_note CHECK ((char_length(note) <= 200))
);

CREATE INDEX invited_emails_list ON public.invited_emails USING btree (list);

alter table public.invited_emails enable row level security;

grant delete, insert, maintain, references, select, trigger, truncate, update on table public.invited_emails to service_role;
